import React, { useState } from 'react';
import { useWidgetDraggable, useWidgetResizable, useWidgetPersistence, useWidgetAI } from '../hooks/useWidgetHooks';
import '../styles/SearchWidget.css';

const SearchWidget = () => {
  const widgetId = 'search-widget';
  const draggable = useWidgetDraggable(widgetId);
  const resizable = useWidgetResizable(widgetId, { width: 400, height: 450 });
  const { data: searchData, updateData } = useWidgetPersistence(widgetId, {
    searchHistory: [],
  });
  const { callGemini, loading: aiLoading } = useWidgetAI();

  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [searchHistory, setSearchHistory] = useState(searchData.searchHistory || []);
  const [activeTab, setActiveTab] = useState('results');
  const [aiAnalysis, setAiAnalysis] = useState(null);

  // AI-Powered search with content extraction
  const performSearch = async (query) => {
    if (!query.trim()) return;

    try {
      // Simulate web search results with AI enhancement
      const prompt = `Generate 5 search results for the query: "${query}"

For each result, provide:
1. Title (relevant to the query)
2. URL (realistic looking)
3. Summary (2-3 sentences)

Format as JSON array with objects containing: title, url, snippet, relevance (0-100)`;

      const result = await callGemini(prompt);
      if (result.success) {
        try {
          const results = JSON.parse(result.content);
          setSearchResults(results);

          // Add to history
          const historyItem = {
            query,
            date: new Date().toLocaleTimeString(),
            preview: results[0]?.title || query,
            resultCount: results.length,
          };
          const newHistory = [historyItem, ...searchHistory].slice(0, 20);
          setSearchHistory(newHistory);
          updateData((prev) => ({ ...prev, searchHistory: newHistory }));
        } catch {
          // Fallback if parsing fails
          const fallbackResults = [
            { title: `Results for "${query}"`, url: 'search.example.com', snippet: 'Search results displayed' },
          ];
          setSearchResults(fallbackResults);
        }
      }
    } catch (error) {
      console.error('Search error:', error);
    }
  };

  // AI Content extraction from search result
  const extractContent = async (resultTitle) => {
    const prompt = `Based on this search result title: "${resultTitle}"

Provide:
1. Key takeaways (top 3 points)
2. Relevance score (0-100)
3. Content category
4. Suggested follow-up searches
5. Data quality assessment

Keep it concise and factual.`;

    const result = await callGemini(prompt);
    if (result.success) {
      setAiAnalysis({
        title: resultTitle,
        analysis: result.content,
        timestamp: new Date().toLocaleTimeString(),
      });
    }
  };

  // AI Analyze search trends
  const analyzeSearchTrends = async () => {
    const queries = searchHistory.map((h) => h.query).join(', ');
    const prompt = `Analyze these search queries and identify trends:

${queries}

Provide:
1. Main topics of interest
2. Search pattern analysis
3. Emerging trends
4. Recommended topics to explore
5. User interest profile

Keep it concise.`;

    const result = await callGemini(prompt);
    if (result.success) {
      alert('Search Trend Analysis:\n\n' + result.content);
    }
  };

  return (
    <div
      {...draggable}
      ref={draggable.ref}
      {...resizable}
      className="widget-container search-widget"
      style={{
        ...draggable.style,
        ...resizable.style,
        position: 'fixed',
        zIndex: 1000,
        backgroundColor: '#0a0e27',
        border: '2px solid #00aaff',
        borderRadius: '8px',
        boxShadow: '0 0 20px rgba(0, 170, 255, 0.3)',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      {/* Header */}
      <div className="widget-header" style={{ borderBottom: '2px solid #00aaff', padding: '12px' }}>
        <div className="widget-title" style={{ color: '#00aaff', fontSize: '16px', fontWeight: 'bold' }}>
          🔍 SEARCH WIDGET
        </div>
        <div className="widget-status" style={{ fontSize: '11px', color: '#0088ff' }}>
          ● AI-POWERED SEARCH
        </div>
      </div>

      {/* Tabs */}
      <div className="search-tabs" style={{ display: 'flex', borderBottom: '1px solid #00aaff', gap: '8px', padding: '8px' }}>
        {['results', 'history', 'analysis'].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            style={{
              background: activeTab === tab ? '#00aaff' : 'transparent',
              color: activeTab === tab ? '#0a0e27' : '#00aaff',
              border: '1px solid #00aaff',
              padding: '6px 12px',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '12px',
              fontWeight: activeTab === tab ? 'bold' : 'normal',
            }}
          >
            {tab.charAt(0).toUpperCase() + tab.slice(1)}
          </button>
        ))}
      </div>

      {/* Content Area */}
      <div
        className="search-content"
        style={{
          flex: 1,
          overflowY: 'auto',
          padding: '12px',
          color: '#00aaff',
          fontSize: '12px',
        }}
      >
        {/* Search Bar */}
        <div style={{ marginBottom: '12px' }}>
          <div style={{ display: 'flex', gap: '6px' }}>
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && performSearch(searchQuery)}
              placeholder="Search the web..."
              style={{
                flex: 1,
                padding: '8px',
                backgroundColor: '#1a1f3a',
                border: '1px solid #00aaff',
                color: '#00aaff',
                borderRadius: '4px',
                fontSize: '12px',
              }}
            />
            <button
              onClick={() => performSearch(searchQuery)}
              style={{
                padding: '8px 12px',
                backgroundColor: '#00aaff',
                color: '#0a0e27',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                fontWeight: 'bold',
                fontSize: '11px',
              }}
            >
              {aiLoading ? '...' : 'Go'}
            </button>
          </div>
        </div>

        {activeTab === 'results' && (
          <div className="search-results">
            {searchResults.length === 0 ? (
              <div style={{ color: '#0088ff', textAlign: 'center', padding: '20px' }}>
                Enter a search query and press Enter
              </div>
            ) : (
              searchResults.map((result, idx) => (
                <div key={idx} style={{ marginBottom: '12px', borderBottom: '1px solid #00aaff33', paddingBottom: '10px' }}>
                  <div style={{ color: '#00ffff', fontWeight: 'bold', fontSize: '12px' }}>
                    {result.title}
                  </div>
                  <div style={{ fontSize: '10px', color: '#0088ff', margin: '4px 0' }}>
                    {result.url || `result-${idx}.com`}
                  </div>
                  <div style={{ fontSize: '11px', color: '#cccccc', margin: '6px 0' }}>
                    {result.snippet || result.summary}
                  </div>
                  {result.relevance && (
                    <div style={{ fontSize: '10px', color: '#00ff88', margin: '4px 0' }}>
                      Relevance: {result.relevance}%
                    </div>
                  )}
                  <button
                    onClick={() => extractContent(result.title)}
                    style={{
                      padding: '4px 8px',
                      fontSize: '10px',
                      backgroundColor: '#00aaff33',
                      border: '1px solid #00aaff',
                      color: '#00aaff',
                      borderRadius: '2px',
                      cursor: 'pointer',
                      marginTop: '6px',
                    }}
                  >
                    {aiLoading ? 'Analyzing...' : 'Extract Content'}
                  </button>
                </div>
              ))
            )}
          </div>
        )}

        {activeTab === 'history' && (
          <div className="search-history">
            <button
              onClick={analyzeSearchTrends}
              disabled={searchHistory.length === 0 || aiLoading}
              style={{
                width: '100%',
                padding: '8px',
                marginBottom: '10px',
                backgroundColor: aiLoading || searchHistory.length === 0 ? '#00aaff66' : '#00aaff',
                color: '#0a0e27',
                border: 'none',
                borderRadius: '4px',
                fontWeight: 'bold',
                cursor: aiLoading || searchHistory.length === 0 ? 'not-allowed' : 'pointer',
                fontSize: '11px',
              }}
            >
              {aiLoading ? 'Analyzing...' : 'Analyze Trends'}
            </button>
            {searchHistory.length === 0 ? (
              <div style={{ color: '#0088ff', textAlign: 'center', padding: '20px' }}>
                No search history yet
              </div>
            ) : (
              searchHistory.map((item, idx) => (
                <div key={idx} style={{ marginBottom: '10px', borderBottom: '1px solid #00aaff33', paddingBottom: '8px' }}>
                  <div style={{ fontWeight: 'bold', color: '#00ffff', fontSize: '12px' }}>
                    {item.query}
                  </div>
                  <div style={{ fontSize: '10px', color: '#0088ff' }}>{item.date}</div>
                  <div style={{ fontSize: '10px', color: '#cccccc', margin: '4px 0' }}>
                    {item.resultCount} results
                  </div>
                  <div style={{ fontSize: '10px', color: '#0088ff' }}>{item.preview}</div>
                </div>
              ))
            )}
          </div>
        )}

        {activeTab === 'analysis' && (
          <div className="search-analysis">
            {aiAnalysis ? (
              <div>
                <div style={{ color: '#00ffff', fontWeight: 'bold', marginBottom: '10px', fontSize: '12px' }}>
                  Analysis: {aiAnalysis.title}
                </div>
                <div style={{ fontSize: '10px', color: '#0088ff', marginBottom: '8px' }}>
                  {aiAnalysis.timestamp}
                </div>
                <div style={{ fontSize: '11px', color: '#cccccc', whiteSpace: 'pre-wrap' }}>
                  {aiAnalysis.analysis}
                </div>
              </div>
            ) : (
              <div style={{ color: '#0088ff', textAlign: 'center', padding: '20px' }}>
                Click "Extract Content" on a search result to analyze it
              </div>
            )}
          </div>
        )}
      </div>

      {/* Resize Handle */}
      <div
        onMouseDown={resizable.onResizeStart}
        style={{
          width: '20px',
          height: '20px',
          position: 'absolute',
          bottom: '0',
          right: '0',
          cursor: 'nwse-resize',
          background: 'linear-gradient(135deg, transparent 50%, #00aaff 50%)',
          borderRadius: '0 0 8px 0',
        }}
      />
    </div>
  );
};

export default SearchWidget;
